/**
 * Query parameter names commonly used in open-redirect gadget chains (CWE-601).
 */
export const OPEN_REDIRECT_QUERY_PARAM_KEYS = ['redirect', 'redirect_uri', 'redirect_url', 'redirecturl', 'next', 'url', 'return', 'returnurl', 'return_url', 'goto', 'destination', 'continue', 'target', 'forward', 'out', 'redir', 'rurl', 'view', 'to'];
const OPEN_REDIRECT_QUERY_PARAM_KEY_SET = new Set(OPEN_REDIRECT_QUERY_PARAM_KEYS.map(key => key.toLowerCase()));
export const isOpenRedirectQueryParamKey = key => OPEN_REDIRECT_QUERY_PARAM_KEY_SET.has(key.toLowerCase());
